;//========================================================================================// FTLDefaultStringEncoding_AC//========================================================================================template<class charT>CFStringEncoding FTLDefaultStringEncoding_AC();template<>inline CFStringEncoding FTLDefaultStringEncoding_AC<char>(){	return kCFStringEncodingMacRoman;}template<>inline CFStringEncoding FTLDefaultStringEncoding_AC<wchar_t>(){	return kCFStringEncodingUnicode;}//========================================================================================// FTLString_AC//========================================================================================#ifndef qHasStdIterator	#ifndef __GNUC__		#define qHasStdIterator 1	#else		#ifdef __STL_USE_NAMESPACES			#define qHasStdIterator 1		#else			#define qHasStdIterator 0		#endif	#endif#endifclass FTLString_AC{public:	// types:#ifdef __GNUC__	typedef std::string_char_traits<char>	traits_type;#else	typedef std::char_traits<char>			traits_type;#endif	typedef char							value_type;	typedef std::allocator<char>			allocator_type;	typedef std::size_t						size_type;	typedef std::ptrdiff_t					difference_type;	typedef char&							reference;	typedef const char&						const_reference;	typedef char*							pointer;	typedef const char*						const_pointer;	class									iterator;	class proxy	// FTLString_AC::proxy acts like a reference into the string. 	{		friend class FTLString_AC;		friend class iterator;		explicit proxy(FTLString_AC& str, size_type pos);	public:		operator char() const	{ return fString[fPos]; }		proxy& operator=(char c);	private:		FTLString_AC&	fString;		size_type		fPos;	};#if qHasStdIterator	class iterator : public std::iterator<std::random_access_iterator_tag, char>#else	class iterator : public std::random_access_iterator<char, ptrdiff_t>#endif	// FTLString_AC::iterator acts like a pointer into the string. 	{		friend class FTLString_AC;		iterator(FTLString_AC& str, size_type pos);	public:		iterator();		iterator(const iterator& iter);		iterator& operator=(const iterator& rhs);		proxy operator*() const;		iterator operator->() const;		iterator& operator++();		iterator operator++(int);		iterator& operator--();		iterator operator--(int);		iterator& operator+=(difference_type n);		iterator operator+(difference_type n);		iterator& operator-=(difference_type n);		iterator operator-(difference_type n);		difference_type operator-(const iterator& rhs) const		{			if (fString != rhs.fString)				ThrowIteratorsMustBeOnSame();			return fPos - rhs.fPos;		}		proxy operator[](size_type i) const;		bool operator==(const iterator& rhs) const;		bool operator!=(const iterator& rhs) const;		bool operator<(const iterator& rhs) const;		bool operator>(const iterator& rhs) const;		bool operator<=(const iterator& rhs) const;		bool operator>=(const iterator& rhs) const;	private:		FTLString_AC*	fString;		size_type		fPos;	};#if qHasStdIterator	class const_iterator : public std::iterator<std::random_access_iterator_tag, char>#else	class const_iterator : public std::random_access_iterator<char, ptrdiff_t>#endif	// FTLString_AC::iterator acts like a const pointer into the string. 	{		friend class FTLString_AC;		const_iterator(const FTLString_AC& str, size_type pos);	public:		const_iterator();		const_iterator(const const_iterator& iter);		const_iterator& operator=(const const_iterator& rhs);		char operator*() const;		const_iterator operator->() const;		const_iterator& operator++();		const_iterator operator++(int);		const_iterator& operator--();		const_iterator operator--(int);		const_iterator& operator+=(difference_type n);		const_iterator operator+(difference_type n);		const_iterator& operator-=(difference_type n);		const_iterator operator-(difference_type n);		difference_type operator-(const const_iterator& rhs) const		{			if (fString != rhs.fString)				ThrowIteratorsMustBeOnSame();			return fPos - rhs.fPos;		}		char operator[](size_type i) const;		bool operator==(const const_iterator& rhs) const;		bool operator!=(const const_iterator& rhs) const;		bool operator<(const const_iterator& rhs) const;		bool operator>(const const_iterator& rhs) const;		bool operator<=(const const_iterator& rhs) const;		bool operator>=(const const_iterator& rhs) const;	private:		const FTLString_AC*	fString;		size_type			fPos;	};	typedef std::reverse_iterator<iterator> reverse_iterator;	typedef std::reverse_iterator<const_iterator> const_reverse_iterator;	static const size_type npos = static_cast<size_type>(-1);	// construct/copy/destroy:	explicit FTLString_AC();	FTLString_AC(const FTLString_AC& str, size_type pos = 0, size_type n = npos);	FTLString_AC(const char* s, size_type n);	FTLString_AC(const char* s);	FTLString_AC(size_type n, char c);	template<class InputIterator>FTLString_AC(InputIterator first, InputIterator last);	FTLString_AC(const std::string& str);	FTLString_AC(CFStringRef cfstr);	~FTLString_AC();	FTLString_AC& operator=(const FTLString_AC& str);	FTLString_AC& operator=(const char* s);	FTLString_AC& operator=(char c);	FTLString_AC& operator=(const std::string& str);	FTLString_AC& operator=(CFStringRef cfstr);	// iterators:	iterator begin();	const_iterator begin() const;	iterator end();	const_iterator end() const;	reverse_iterator rbegin();	const_reverse_iterator rbegin() const;	reverse_iterator rend();	const_reverse_iterator rend() const;	// capacity:	size_type size() const;	size_type length() const;	size_type max_size() const;	void resize(size_type n, char c);	void resize(size_type n);	size_type capacity() const;	void reserve(size_type res_arg = 0);	void clear();	bool empty() const;	// element access:	char operator[](size_type pos) const;	proxy operator[](size_type pos);	char at(size_type n) const;	proxy at(size_type n);	// modifiers:	FTLString_AC& operator+=(const FTLString_AC& str);	FTLString_AC& operator+=(const char* s);	FTLString_AC& operator+=(char c);	FTLString_AC& append(const FTLString_AC& str);	FTLString_AC& append(const FTLString_AC& str, size_type pos, size_type n);	FTLString_AC& append(const char* s, size_type n);	FTLString_AC& append(const char* s);	FTLString_AC& append(size_type n, char c);	template<class InputIterator> FTLString_AC& append(InputIterator first, InputIterator last);	FTLString_AC& assign(const FTLString_AC&);	FTLString_AC& assign(const FTLString_AC& str, size_type pos, size_type n);	FTLString_AC& assign(const char* s, size_type n);	FTLString_AC& assign(const char* s);	FTLString_AC& assign(size_type n, char c);	template<class InputIterator> FTLString_AC& assign(InputIterator first, InputIterator last);	FTLString_AC& insert(size_type pos1, const FTLString_AC& str);	FTLString_AC& insert(size_type pos1, const FTLString_AC& str, size_type pos2, size_type n);	FTLString_AC& insert(size_type pos, const char* s, size_type n);	FTLString_AC& insert(size_type pos, const char* s);	FTLString_AC& insert(size_type pos, size_type n, char c);	iterator insert(iterator p, char c = char());	void insert(iterator p, size_type n, char c);	template<class InputIterator> void insert(iterator p, InputIterator first, InputIterator last);	FTLString_AC& erase(size_type pos = 0, size_type n = npos);	iterator erase(iterator position);	iterator erase(iterator first, iterator last);	FTLString_AC& replace(size_type pos1, size_type n1, const FTLString_AC& str);	FTLString_AC& replace(size_type pos1, size_type n1, const FTLString_AC& str, size_type pos2, size_type n2);	FTLString_AC& replace(size_type pos, size_type n1, const char* s, size_type n2);	FTLString_AC& replace(size_type pos, size_type n1, const char* s);	FTLString_AC& replace(size_type pos, size_type n1, size_type n2, char c);	FTLString_AC& replace(iterator i1, iterator i2, const FTLString_AC& str);	FTLString_AC& replace(iterator i1, iterator i2, const char* s, size_type n);	FTLString_AC& replace(iterator i1, iterator i2, const char* s);	FTLString_AC& replace(iterator i1, iterator i2, size_type n, char c);	template<class InputIterator> FTLString_AC& replace(iterator i1, iterator i2, InputIterator j1, InputIterator j2);	size_type copy(char* s, size_type n, size_type pos = 0) const;	void swap(FTLString_AC&);	// string operations:	const char* c_str() const;	// explicit	const char* data() const;	allocator_type get_allocator() const;	size_type find(const FTLString_AC& str, size_type pos = 0) const;	size_type find(const char* s, size_type pos, size_type n) const;	size_type find(const char* s, size_type pos = 0) const;	size_type find(char c, size_type pos = 0) const;	size_type rfind(const FTLString_AC& str, size_type pos = npos) const;	size_type rfind(const char* s, size_type pos, size_type n) const;	size_type rfind(const char* s, size_type pos = npos) const;	size_type rfind(char c, size_type pos = npos) const;	size_type find_first_of(const FTLString_AC& str, size_type pos = 0) const;	size_type find_first_of(const char* s, size_type pos, size_type n) const;	size_type find_first_of(const char* s, size_type pos = 0) const;	size_type find_first_of(char c, size_type pos = 0) const;	size_type find_last_of(const FTLString_AC& str, size_type pos = npos) const;	size_type find_last_of(const char* s, size_type pos, size_type n) const;	size_type find_last_of(const char* s, size_type pos = npos) const;	size_type find_last_of(char c, size_type pos = npos) const;	size_type find_first_not_of(const FTLString_AC& str, size_type pos = 0) const;	size_type find_first_not_of(const char* s, size_type pos, size_type n) const;	size_type find_first_not_of(const char* s, size_type pos = 0) const;	size_type find_first_not_of(char c, size_type pos = 0) const;	size_type find_last_not_of(const FTLString_AC& str, size_type pos = npos) const;	size_type find_last_not_of(const char* s, size_type pos, size_type n) const;	size_type find_last_not_of(const char* s, size_type pos = npos) const;	size_type find_last_not_of(char c, size_type pos = npos) const;	FTLString_AC substr(size_type pos = 0, size_type n = npos) const;	int compare(const FTLString_AC& str) const;	int compare(size_type pos1, size_type n1, const FTLString_AC& str) const;	int compare(size_type pos1, size_type n1, const FTLString_AC& str, size_type pos2, size_type n2) const;	int compare(const char* s) const;	int compare(size_type pos1, size_type n1, const char* s, size_type n2 = npos) const;	// conversion		std::string AsString() const;	CFStringRef CFString() const;	CFMutableStringRef CFMutableString();	// testing#if qDebug	static void Test();#endif	// dataprivate:	CAutoCFMutableString_AC	fCFString;};//----------------------------------------------------------------------------------------// non-member functions//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// operator+//----------------------------------------------------------------------------------------FTLString_AC::iterator operator+(FTLString_AC::difference_type n, const FTLString_AC::iterator& rhs);FTLString_AC::const_iterator operator+(FTLString_AC::difference_type n, const FTLString_AC::const_iterator& rhs);FTLString_AC operator+(const FTLString_AC& lhs, const FTLString_AC& rhs);FTLString_AC operator+(const char* lhs, const FTLString_AC& rhs);FTLString_AC operator+(char lhs, const FTLString_AC& rhs);FTLString_AC operator+(const FTLString_AC& lhs, const char* rhs);FTLString_AC operator+(const FTLString_AC& lhs, char rhs);//----------------------------------------------------------------------------------------// operator==//----------------------------------------------------------------------------------------bool operator==(const FTLString_AC& lhs, const FTLString_AC& rhs);bool operator==(const char* lhs, const FTLString_AC& rhs);bool operator==(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// operator!=//----------------------------------------------------------------------------------------bool operator!=(const FTLString_AC& lhs, const FTLString_AC& rhs);bool operator!=(const char* lhs, const FTLString_AC& rhs);bool operator!=(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// operator<//----------------------------------------------------------------------------------------bool operator<(const FTLString_AC& lhs, const FTLString_AC& rhs);bool operator<(const char* lhs, const FTLString_AC& rhs);bool operator<(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// operator>//----------------------------------------------------------------------------------------bool operator>(const FTLString_AC& lhs, const FTLString_AC& rhs);bool operator>(const char* lhs, const FTLString_AC& rhs);bool operator>(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// operator<=//----------------------------------------------------------------------------------------bool operator<=(const FTLString_AC& lhs, const FTLString_AC& rhs);bool operator<=(const char* lhs, const FTLString_AC& rhs);bool operator<=(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// operator>=//----------------------------------------------------------------------------------------bool operator>=(const FTLString_AC& lhs, const FTLString_AC& rhs);//----------------------------------------------------------------------------------------// operator>=//----------------------------------------------------------------------------------------bool operator>=(const char* lhs, const FTLString_AC& rhs);bool operator>=(const FTLString_AC& lhs, const char* rhs);//----------------------------------------------------------------------------------------// swap//----------------------------------------------------------------------------------------void swap(FTLString_AC& lhs, FTLString_AC& rhs);//----------------------------------------------------------------------------------------// Inserters and extractors//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// operator>>//----------------------------------------------------------------------------------------std::istream& operator>>(std::istream& is, FTLString_AC& str);//----------------------------------------------------------------------------------------// operator<<//----------------------------------------------------------------------------------------std::ostream& operator<<(std::ostream& os, const FTLString_AC& str);//----------------------------------------------------------------------------------------// getline//----------------------------------------------------------------------------------------std::istream& getline(std::istream& is, FTLString_AC& str, char delim);//----------------------------------------------------------------------------------------// getline//----------------------------------------------------------------------------------------std::istream& getline(std::istream& is, FTLString_AC& str);//========================================================================================// FTLString_AC//========================================================================================template<class InputIterator>FTLString_AC::FTLString_AC(InputIterator first, InputIterator last)	:	fCFString(){	std::string temp(first, last);	fCFString = __CFString::CreateMutableWithBytes(temp.data(), temp.size(), false, __CFString::kUnlimited);}template<class InputIterator>FTLString_AC& FTLString_AC::append(InputIterator first, InputIterator last){	std::string temp(first, last);	append(temp.data(), temp.size());	return *this;}template<class InputIterator>FTLString_AC& FTLString_AC::assign(InputIterator first, InputIterator last){	std::string temp(first, last);	fCFString = __CFString::CreateMutableWithBytes(temp.data(), temp.size(), false, __CFString::kUnlimited);}template<class InputIterator>void FTLString_AC::insert(iterator p, InputIterator first, InputIterator last){#if 0	// space efficient	if (p.fString != this)		ThrowIteratorMustBeOnThis();	size_type pos = p.fPos;	while (first != last)		insert(pos++, *first++);#else	// time efficient	insert(p.fPos, FTLString_AC(first, last));#endif}template<class InputIterator>FTLString_AC& FTLString_AC::replace(iterator i1, iterator i2, InputIterator j1, InputIterator j2){	return replace(i1, i2, FTLString_AC(j1, j2));}#endif // __FTLString_AC__